content.content:
1	#pragma once
2	
3	// The subject of the printer panel's conversation: what the model is told and
4	// may call there, and the cards the page draws in the thread.
5	//
6	// The conversation is the whole panel. The model does the understanding --
7	// which printer someone has, what changed on one they own, how to reach it --
8	// and acts through the session's tools, which check requests against the
9	// printer data and carry them out. printer_connect collects its credential in
10	// a local form so it never passes through the model. The other things to tap
11	// are Undo on an added printer's receipt and the printer form, where the
12	// person picks a printer from the lists themselves; the model hears about
13	// either in a note.
14	//
15	// A session is opened for one printer question -- add a printer, change this
16	// one, connect this one -- and is discarded when the panel closes. Nothing
17	// here is written to the project: AgentHost keeps the thread in an in-memory
18	// document, and printers are saved through IPrinterBackend, which owns the
19	// only route to Orca.
20	//
21	// GUI-free and Orca-free: the panel supplies both interfaces, and the tests
22	// supply fakes.
23	
24	#include "PrinterBackend.hpp"
25	#include "slic3r/GUI/JusPrin/Agent/AgentProtocol.hpp"
26	#include "slic3r/GUI/JusPrin/Agent/AgentService.hpp"
27	#include "slic3r/GUI/JusPrin/Agent/ToolExecutionCoordinator.hpp"
28	
29	#include <nlohmann/json.hpp>
30	
31	#include <chrono>
32	#include <future>
33	#include <map>
34	#include <optional>
35	#include <string>
36	#include <vector>
37	
38	namespace Slic3r::GUI::JusPrin::PrinterSetup {
39	
40	// Which question the panel was opened for.
41	enum class ConversationMode { Add, Change, Connect };
42	
43	// Everything the conversation needs from its owner. The panel is the only
44	// implementation; the tests use a recording fake.
45	class IConversationHost
46	{
47	public:
48	    virtual ~IConversationHost() = default;
49	
50	    // The chat so far, for a report; see connection_chat_record.
51	    virtual nlohmann::json chat_record() const = 0;
52	    // A line in the thread stating what happened, which the model reads as
53	    // the app's own words. Returns its message id.
54	    virtual std::string post_note(const std::string& text) = 0;
55	    // The panel's first line, shown as the agent's. Returns its message id.
56	    virtual std::string post_opening(const std::string& text) = 0;
57	    // The model answers next, from the conversation as it stands.
58	    virtual void start_turn() = 0;
59	    // The cards in the thread, or what the model is told, have changed.
60	    virtual void session_changed() = 0;
61	    // The page sent new instructions for the model.
62	    virtual void profile_changed() = 0;
63	    // The panel is done: restore its originating workspace.
64	    virtual void close_panel() = 0;
65	    // Opens `url` in the person's default browser. False when none opened.
66	    virtual bool open_in_browser(const std::string& url) = 0;
67	    // This app's version, as an issue report gives it.
68	    virtual std::string app_version() const = 0;
69	    // Home's printer list is out of date. `added` names a printer this
70	    // session just added, which Home leads with; empty for any other change.
71	    virtual void printers_changed(const std::string& added = {}) = 0;
72	};
73	
74	// What a connection report says of a chat: its messages as {role, text} under
75	// "turns", and its connection tools' calls under "tools". The access code or
76	// API key goes into a form of its own and is in neither.
77	nlohmann::json connection_chat_record(const std::vector<Agent::ConversationMessage>& messages,
78	                                      const std::vector<Agent::ToolActivity>&        activities);
79	
80	// The GitHub page for a new JusPrin issue, filled in with `title` and `body`
81	// and ending in the app's own `footer`. A body that would take the link past
82	// kIssueLinkLimit bytes is cut, never the footer, and `shortened` says so.
83	inline constexpr std::size_t kIssueLinkLimit = 8000;
84	struct IssueLink
85	{
86	    std::string url;
87	    bool        shortened{false};
88	};
89	IssueLink issue_link(const std::string& title, const std::string& body, const std::string& footer);
90	
91	class PrinterConversation
92	{
93	public:
94	    PrinterConversation(IPrinterBackend& backend, IConversationHost& host);
95	
96	    // Starts a session. `printer_name` names the printer a Change or Connect
97	    // session is about and is ignored when adding: a saved printer, or for a
98	    // change also the stock profile the project has selected. The caller has
99	    // checked that it is there.
100	    void start(ConversationMode mode, const std::string& printer_name = {});
101	
102	    ConversationMode   mode() const { return m_mode; }
103	    const std::string& printer_name() const { return m_printer_name; }
104	
105	    // What the model is told and may call: every printer tool, always.
106	    Agent::AgentSessionProfile profile() const;
107	    // What the page draws the panel and writes the instructions from.
108	    nlohmann::json state_json() const;
109	
110	    // A message from the panel's own page. Returns false for anything that is
111	    // not one of ours.
112	    bool handle_page_message(const std::string& type, const nlohmann::json& payload);
113	
114	    // Checks printer_connect before its input form is shown, and titles it.
115	    std::optional<Agent::ToolError> preflight_tool(Agent::ToolHandler handler, Agent::ToolActivity& activity);
116	    // The session's own tools. Returns an unhandled result for any other
117	    // handler, so the host's own extensions still run.
118	    Agent::ToolExecutionCoordinator::ExtensionResult execute_tool(Agent::ToolHandler         handler,
119	                                                                 const Agent::ToolActivity& activity);
120	    // What the model reads back for a call to this session's tools.
121	    std::optional<nlohmann::json> tool_output(const Agent::ToolActivity& activity) const;
122	    // The skill for this printer's connection type, chosen by its vendor,
123	    // from the moment the chat has a saved printer: added in it, or the one it
124	    // was opened for. A Bambu Lab printer's comes with issue_report_open, for
125	    // someone stuck who wants the developers to know.
126	    std::optional<Agent::SessionSkill> connection_skill() const;
127	
128	    // Called on the panel's pump. Picks up the printer form's options once
129	    // they are read. While a connection is being verified, looks at most once
130	    // a second, and once it settles says how in a note and has the model
131	    // answer. Does the same for a network search: when it first finds a
132	    // printer, and when it has found none after about 15 seconds, or cannot
133	    // hear any because this app does not hold the port they announce on.
134	    void tick(std::chrono::steady_clock::time_point now);
135	
136	    // A settings tool this session ran has settled. A copy of the printer
137	    // saved in place of a stock profile is the printer from then on.
138	    void tool_settled(const Agent::ToolActivity& activity);
139	
140	    // The printer panel's own tools, and the settings tools a session also
141	    // offers for the printer it is about.
142	    static std::vector<std::string> session_tools();
143	    static std::vector<std::string> settings_tools();
144	
145	private:
146	    using Result = Agent::ToolExecutionCoordinator::ExtensionResult;
147	    Result identify(const nlohmann::json& arguments, const std::string& message_id);
148	    Result add(const nlohmann::json& arguments, const std::string& message_id);
149	    Result change(const nlohmann::json& arguments);
150	    Result connection_status(const std::string& name, const std::string& message_id);
151	    Result request_credential(const nlohmann::json& arguments, const std::string& action_id);
152	    Result open_issue(const nlohmann::json& arguments);
153	    void   connect(const nlohmann::json& arguments, const std::string& credential);
154	    // Why printer_connect refused `asked`, from what the app has observed.
155	    std::string    unknown_device_text(const PrinterConnectionInfo& info, const std::string& asked) const;
156	    // How far the network search has got, for a refusal and for the status.
157	    std::string    search_text() const;
158	    nlohmann::json search_json(const PrinterConnectionInfo& info) const;
159	    void           watch_search(std::chrono::steady_clock::time_point now);
160	    // The notice that Bambu's network plug-in is missing, under this message:
161	    // drawn by the app, once a session, whatever the model says around it.
162	    void show_plugin_needed(const std::string& message_id);
163	    // Its Install button: runs the installer, and tells the model if the
164	    // plug-in is there afterwards.
165	    void install_network_plugin();
166	    // A connection attempt failed; `message_id` is the note that says so.
167	    // The second failure in a session puts the report card under it.
168	    void connection_failed(const std::string& message_id);
169	    // The person's answer on that card.
170	    void answer_report(const std::string& block_id, bool send);
171	    // Drops a connection attempt still waiting, so what the printer answers
172	    // later is never read.
173	    void abandon_connection();
174	    // Undo on an added printer's receipt: removes that printer.
175	    void undo_add(const std::string& block_id);
176	    // The printer form: opened from the header, then asked for one model's
177	    // options, then finished or closed. Only finishing saves anything.
178	    void open_form();
179	    void ask_form_options(const nlohmann::json& payload);
180	    void finish_form(const nlohmann::json& payload);
181	    nlohmann::json form_json() const;
182	
183	    SavedPrinter          saved(const std::string& name) const;
184	    // The printer the session is about: a saved one, or the stock profile a
185	    // change was opened for.
186	    SavedPrinter          about() const;
187	    const CatalogPrinter* catalog_entry(const std::string& id) const;
