149	// A report holds neither an access code nor an API key. The form's credential
150	// never reaches the chat; this takes out what a person may type into the chat
151	// anyway, and a printer's serial, which a report has no need of: a key's own
152	// shape, and any run of six or more letters and digits with a digit in it. A
153	// code of letters alone reads as a word, which is why the person is shown the
154	// report and told to look.
155	std::string without_secrets(const std::string& text)
156	{
157	    static const std::regex key("sk-[A-Za-z0-9_-]{6,}");
158	    static const std::regex token("[A-Za-z0-9]{6,}");
159	    const std::string       no_keys = std::regex_replace(text, key, "[hidden]");
160	    std::string             out;
161	    std::size_t             from = 0;
162	    for (auto it = std::sregex_iterator(no_keys.begin(), no_keys.end(), token); it != std::sregex_iterator(); ++it) {
163	        const std::string word = it->str();
164	        out += no_keys.substr(from, it->position() - from);
165	        out += std::any_of(word.begin(), word.end(), [](unsigned char c) { return std::isdigit(c) != 0; }) ? "[hidden]" : word;
166	        from = it->position() + word.size();
167	    }
168	    return out + no_keys.substr(from);
169	}
