184	std::string percent_encoded(const std::string& text)
185	{
186	    static const char* const digits = "0123456789ABCDEF";
187	    std::string              out;
188	    for (const unsigned char c : text)
189	        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '.' || c == '_' || c == '~')
190	            out += static_cast<char>(c);
191	        else
192	            out += {'%', digits[c >> 4], digits[c & 15]};
193	    return out;
194	}
195	
196	json without_secrets(const json& value)
197	{
198	    if (value.is_string())
199	        return without_secrets(value.get<std::string>());
200	    json out = value;
201	    if (value.is_structured())
202	        for (auto it = out.begin(); it != out.end(); ++it)
203	            *it = without_secrets(json(*it));
204	    return out;
205	}
