338	void PrinterConversation::show_plugin_needed(const std::string& message_id)
339	{
340	    m_needs_plugin = true;
341	    const bool shown = std::any_of(m_blocks.begin(), m_blocks.end(), [](const json& block) {
342	        return block.value("kind", std::string()) == "plugin" && !block.value("installed", false);
343	    });
344	    if (shown)
345	        return;
346	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id}, {"kind", "plugin"}});
347	    m_host.session_changed();
348	}
349	
350	void PrinterConversation::install_network_plugin()
351	{
352	    if (!m_needs_plugin || m_printer_name.empty())
353	        return;
354	    m_backend.install_network_plugin();
355	    // Closing the installer, or a download that failed, leaves the notice
356	    // and its button as they were; Orca's dialog has said what happened.
357	    if (m_backend.connection(m_printer_name).needs_network_plugin)
358	        return;
359	    m_needs_plugin = false;
360	    for (json& block : m_blocks)
361	        if (block.value("kind", std::string()) == "plugin")
362	            block["installed"] = true;
363	    // Discovery could not start without the plug-in; the next status check
364	    // starts it.
365	    m_prepared.clear();
366	    m_search.reset();
367	    m_host.post_note("Bambu's network plug-in is installed now, so " + m_printer_name + " can be connected.");
368	    m_host.session_changed();
369	    m_host.start_turn();
370	}
