403	json PrinterConversation::context_json() const
404	{
405	    json context = json::object();
406	    if (m_mode == ConversationMode::Add) {
407	        json printers = json::array();
408	        for (const CatalogPrinter& printer : m_backend.catalog())
409	            printers.push_back(json::array({printer.id, printer.display_name(), printer.build_volume}));
410	        json network = json::array();
411	        for (const DiscoveredPrinter& found : m_network)
412	            network.push_back(json{{"name", found.name}, {"serial", found.stable_id}});
413	        context["printers"] = std::move(printers);
414	        context["network"]  = std::move(network);
415	    }
416	    if (const SavedPrinter printer = about(); !printer.name.empty()) {
417	        context["printer"]             = printer_json(printer);
418	        context["printer"]["provider"] = printer.vendor_id == "BBL" ? "bambu" : "host";
419	        if (printer.stock) {
420	            context["printer"]["stock"]    = true;
421	            context["printer"]["copyName"] = printer.copy_name;
422	        }
423	        if (m_needs_plugin)
424	            context["printer"]["needsNetworkPlugin"] = true;
425	    }
426	    return context;
427	}
