458	
459	json connection_chat_record(const std::vector<Agent::ConversationMessage>& messages, const std::vector<ToolActivity>& activities)
460	{
461	    json turns = json::array();
462	    for (const Agent::ConversationMessage& message : messages)
463	        if (!message.text.empty()) // a turn that only called a tool
464	            turns.push_back({{"role", message.role == Agent::MessageRole::User ? "person" :
465	                                      message.role == Agent::MessageRole::Note ? "app" :
466	                                                                                 "model"},
467	                             {"text", message.text}});
468	    json tools = json::array();
469	    for (const ToolActivity& activity : activities) {
470	        if (activity.tool != "printer_connect" && activity.tool != "printer_connection_status")
471	            continue;
472	        tools.push_back({{"tool", activity.tool},
473	                         {"arguments", json::parse(activity.arguments_json, nullptr, false)},
474	                         {"output", activity.error ? json(activity.error->code + ": " + activity.error->message) :
475	                                                     json::parse(activity.result_json, nullptr, false)}});
476	    }
477	    return json{{"turns", std::move(turns)}, {"tools", std::move(tools)}};
478	}
