638	Result PrinterConversation::execute_tool(ToolHandler handler, const ToolActivity& activity)
639	{
640	    const json arguments = json::parse(activity.arguments_json);
641	    switch (handler) {
642	    case ToolHandler::PrinterIdentify: return identify(arguments, activity.correlation_id);
643	    case ToolHandler::PrinterAdd: return add(arguments, activity.correlation_id);
644	    case ToolHandler::PrinterChange: return change(arguments);
645	    case ToolHandler::PrinterConnectionStatus: return connection_status(m_printer_name, activity.correlation_id);
646	    case ToolHandler::PrinterConnect: return request_credential(arguments, activity.action_id);
647	    case ToolHandler::IssueReportOpen: return open_issue(arguments);
648	    default: return {};
649	    }
650	}
