823	void PrinterConversation::connect(const json& arguments, const std::string& credential)
824	{
825	    const std::string name   = arguments.at("printerName");
826	    const std::string target = arguments.at("target");
827	    const std::string problem =
828	        arguments.at("provider") == "bambu" ?
829	            m_backend.connect_printer(name, arguments.at("deviceId"), credential) :
830	            m_backend.connect_host(name, arguments.at("hostType"), arguments.at("address"), credential);
831	    if (!problem.empty()) {
832	        connection_failed(m_host.post_note("Connection to " + target + " failed: " + problem));
833	        m_host.session_changed();
834	        m_host.start_turn();
835	        return;
836	    }
837	    m_connecting = name;
838	    m_last_look  = {};
839	    m_host.session_changed();
840	}
