859	void PrinterConversation::answer_report(const std::string& block_id, bool send)
860	{
861	    for (json& block : m_blocks) {
862	        if (block.value("id", std::string()) != block_id || block.value("kind", std::string()) != "report" || block.contains("answer"))
863	            continue;
864	        if (send) {
865	            const std::string kept = m_backend.keep_connection_report(block.at("report").get<std::string>());
866	            block["answer"] = kept.empty() ? "failed" : "kept";
867	            block["path"]   = kept;
868	        } else
869	            block["answer"] = "declined";
870	        m_host.post_note(!send                     ? "The person chose not to send the report." :
871	                         block["answer"] == "kept" ? "The person chose to send the report. Sending is not built yet, so it is saved on "
872	                                                     "this computer and has not reached the developers." :
873	                                                     "The person chose to send the report, and it could not be saved.");
874	        m_host.session_changed();
875	        return;
876	    }
877	}
