879	// -- An issue for the developers --------------------------------------------
880	
881	IssueLink issue_link(const std::string& title, const std::string& body, const std::string& footer)
882	{
883	    static const std::string page   = "https://github.com/TheSpaghettiDetective/JusPrin/issues/new";
884	    static const std::string marker = percent_encoded("\n\n(Cut short to fit the link.)");
885	    const std::string        start  = page + "?title=" + percent_encoded(title) + "&body=";
886	    const std::string        end    = percent_encoded(footer);
887	    const std::string        whole  = percent_encoded(body);
888	    if (start.size() + whole.size() + end.size() <= kIssueLinkLimit)
889	        return {start + whole + end, false};
890	    if (start.size() + marker.size() + end.size() > kIssueLinkLimit)
891	        throw std::logic_error("An issue's title and footer leave no room for its body");
892	    // Whole characters, so the cut never splits one.
893	    const std::size_t room = kIssueLinkLimit - start.size() - marker.size() - end.size();
894	    std::string       kept;
895	    for (std::size_t from = 0; from < body.size();) {
896	        std::size_t next = from + 1;
897	        while (next < body.size() && (static_cast<unsigned char>(body[next]) & 0xC0) == 0x80)
898	            ++next;
899	        const std::string character = percent_encoded(body.substr(from, next - from));
900	        if (kept.size() + character.size() > room)
901	            break;
902	        kept += character;
903	        from = next;
904	    }
905	    return {start + kept + marker + end, true};
906	}
