908	Result PrinterConversation::open_issue(const json& arguments)
909	{
910	    // The tool is offered only with the connection skill, and the footer
911	    // below is the Bambu Lab one: another connection type's needs its own.
912	    const std::optional<Agent::SessionSkill> skill = connection_skill();
913	    if (!skill || skill->trigger != Agent::Protocol::SkillTrigger::kConnectBambu)
914	        throw std::logic_error("issue_report_open ran in a printer chat without the Bambu Lab connection skill in force");
915	    const SavedPrinter          printer = saved(m_printer_name);
916	    const PrinterConnectionInfo info    = m_backend.connection(m_printer_name);
917	    std::vector<std::string>    known{printer.device_id, info.device_id, info.address};
918	    for (const ConnectionCandidate& candidate : info.candidates) {
919	        known.push_back(candidate.id);
920	        known.push_back(candidate.address);
921	    }
922	    // The app's own facts, which the model may have wrong or left out.
923	    const std::string footer = "\n\n---\nApp version: " + m_host.app_version() + "\nConnection: Bambu Lab, LAN mode\nPrinter: " +
924	                               printer.model;
925	    const IssueLink link = issue_link(for_public(arguments.at("title").get<std::string>(), known),
926	                                    for_public(arguments.at("body").get<std::string>(), known), footer);
927	    if (!m_host.open_in_browser(link.url))
928	        return refuse("failed", "The app could not open the person's browser, so no issue page is open.");
929	    std::string message = "The new issue page is open in the person's browser, filled in. Nothing has been filed: it is filed "
930	                          "only when they press Submit on it, signed in to GitHub.";
931	    if (link.shortened)
932	        message += " The body was too long for the link, so its end was cut; they can add the rest on the page.";
933	    return ok(json{{"state", "opened"}, {"shortened", link.shortened}, {"message", message}});
934	}
