1153	void PrinterConversation::open_form()
1154	{
1155	    // A printer is added in an Add session only, as printer_add is.
1156	    if (m_mode != ConversationMode::Add)
1157	        return;
1158	    // An earlier form's read is waited for first: the backend's copy of the
1159	    // person's own presets is what that read is using.
1160	    m_form.reset();
1161	    m_backend.prepare_setup_options();
1162	    PrinterForm form;
1163	    // A machine that already has a printer is that printer, and the form
1164	    // adds new ones; a model the catalogue lacks cannot be set up from it.
1165	    const std::vector<SavedPrinter> printers = m_backend.saved_printers();
1166	    for (DiscoveredPrinter& found : m_backend.nearby_printers()) {
1167	        if (std::any_of(printers.begin(), printers.end(),
1168	                        [&found](const SavedPrinter& printer) { return printer.device_id == found.stable_id; }))
1169	            continue;
1170	        const auto& catalog = m_backend.catalog();
1171	        const auto  model   = std::find_if(catalog.begin(), catalog.end(), [&found](const CatalogPrinter& printer) {
1172	            return !printer.device_model_id.empty() && printer.device_model_id == found.device_model_id;
1173	        });
1174	        if (model != catalog.end())
1175	            form.nearby.emplace_back(std::move(found), model->id);
1176	    }
1177	    m_form = std::move(form);
1178	    m_host.session_changed();
1179	}
