1195	    m_form->error.clear();
1196	    // A read still running for the last choice is waited for here; its
1197	    // answer is no longer wanted.
1198	    m_form->reading = std::async(std::launch::async, [&backend = m_backend, id, nozzle] { return backend.setup_options(id, nozzle); });
1199	    m_host.session_changed();
