1202	void PrinterConversation::finish_form(const json& payload)
1203	{
1204	    if (!m_form)
1205	        return;
1206	    const std::string     id      = payload.value("catalogId", std::string());
1207	    const double          nozzle  = payload.value("nozzle", 0.);
1208	    const CatalogPrinter* printer = catalog_entry(id);
1209	    // The page finishes from the options it was sent; anything else is a
1210	    // page out of step with the app, and nothing is saved from it.
1211	    const auto refuse_form = [this](const std::string& why) {
1212	        m_form->error = why;
1213	        m_host.session_changed();
1214	    };
1215	    const std::optional<SetupOptions>& options = m_form->options;
1216	    if (printer == nullptr || !options || options->catalog_id != id || options->nozzle != nozzle || !options->error.empty())
1217	        return refuse_form(options && !options->error.empty() ? options->error : "The form was out of date. Choose the printer again.");
1218	
1219	    std::optional<int> plate;
1220	    std::string        plate_label;
1221	    if (!options->plates.empty()) {
1222	        const int  type  = payload.value("plate", 0);
1223	        const auto found = std::find_if(options->plates.begin(), options->plates.end(),
1224	                                        [type](const PlateOption& option) { return option.type == type; });
1225	        if (found == options->plates.end())
1226	            return refuse_form("Choose the plate on this printer.");
1227	        plate       = type;
1228	        plate_label = found->label;
1229	    }
1230	
1231	    // The filament to start with: one that fits, which is installed with
1232	    // the printer; one of the person's own; one made for other printers,
1233	    // which is copied for this one; or a preset the person makes in
1234	    // OrcaSlicer's Create filament window once the printer is added.
1235	    const bool        create   = payload.value("create", false);
1236	    const std::string filament = create ? std::string() : payload.value("filament", std::string());
1237	    const auto        in       = [&filament](const std::vector<FilamentOption>& list) -> const FilamentOption* {
1238	        const auto found = std::find_if(list.begin(), list.end(), [&filament](const FilamentOption& option) { return option.name == filament; });
1239	        return found == list.end() ? nullptr : &*found;
1240	    };
1241	    const FilamentOption* fitting = filament.empty() ? nullptr : in(options->filaments);
1242	    const FilamentOption* other   = filament.empty() ? nullptr : in(options->others);
1243	    const FilamentOption* own     = filament.empty() ? nullptr : in(options->own);
1244	    if (!filament.empty() && fitting == nullptr && other == nullptr && own == nullptr)
1245	        return refuse_form("That filament is no longer on the list. Choose another.");
1246	
1247	    const std::string device = payload.value("deviceId", std::string());
1248	    const auto        found  = std::find_if(m_form->nearby.begin(), m_form->nearby.end(),
1249	                                            [&device](const auto& entry) { return entry.first.stable_id == device; });
1250	    if (!device.empty() && (found == m_form->nearby.end() || found->second != id))
1251	        return refuse_form("That printer is no longer on the list. Choose it again.");
1252	
1253	    // The printer is installed with a filament that fits: the chosen one, or
1254	    // the profile's default until the chosen one is in place.
1255	    AddPrinterRequest request{printer->vendor_id, printer->model_id, number_text(nozzle),
1256	                              fitting != nullptr ? fitting->name : options->default_filament, printer->display_name(), device, plate};
1257	    SavedPrinter      added;
1258	    if (const std::string problem = m_backend.add_printer(request, added); !problem.empty())
1259	        return refuse_form(problem);
1260	    const SavedPrinter now = saved(added.name);
1261	    if (now.name.empty())
1262	        throw std::logic_error("A successful add did not save a printer");
1263	
1264	    const auto label_of = [&options](const std::string& name) {
1265	        for (const auto* list : {&options->filaments, &options->others, &options->own})
1266	            for (const FilamentOption& option : *list)
1267	                if (option.name == name)
1268	                    return option.label;
1269	        return name;
1270	    };
1271	    std::string starting = fitting != nullptr ? fitting->label : label_of(options->default_filament);
1272	    std::string filament_note;
1273	    if (own != nullptr || other != nullptr) {
1274	        const FilamentOption& chosen = own != nullptr ? *own : *other;
1275	        const bool            copy   = !chosen.made_for.empty();
1276	        std::string           used;
1277	        if (const std::string problem = m_backend.start_with_filament(now.name, chosen.name, copy, used); !problem.empty())
1278	            filament_note = " " + chosen.label + " could not be used: " + problem + " It starts with " + starting + ".";
1279	        else if (copy)
1280	            starting = "a copy of " + chosen.label + " saved for this printer as " + used;
1281	        else
1282	            starting = "their own preset " + used;
1283	    }
1284	    if (create) {
1285	        const std::string made = m_backend.create_filament_preset(now.name);
1286	        filament_note = made.empty() ? " The person opened the Create filament window and no new preset for this printer is in slot 1, so it starts with " +
1287	                                           starting + "."
1288	                                     : " The person made the filament preset " + made + " in the Create filament window; it is in slot 1.";
1289	    }
1290	
1291	    std::string note = "The person added " + now.name + " themselves with the printer form: " + printer->display_name() + ", " +
1292	                       number_text(nozzle) + " mm nozzle";
1293	    if (!plate_label.empty())
1294	        note += ", " + plate_label;
1295	    if (!create && filament_note.empty() && !starting.empty())
1296	        note += ", starting with " + starting;
1297	    note += "." + filament_note;
1298	    if (!device.empty())
1299	        note += " It is linked to the printer " + found->first.name + ", which is not connected yet.";
1300	
1301	    m_form.reset();
1302	    m_printer_name = now.name;
1303	    m_added[id]    = now.name;
1304	    m_host.post_note(note);
1305	    m_host.printers_changed(now.name);
1306	    m_host.session_changed();
1307	    m_host.start_turn();
1308	}
