286	void PrinterConversation::start(ConversationMode mode, const std::string& printer_name)
287	{
288	    // An attempt the last session left waiting -- its panel closed meanwhile
289	    // -- is dropped before this session can read, and save, its outcome.
290	    abandon_connection();
291	    m_mode         = mode;
292	    m_printer_name = mode == ConversationMode::Add ? std::string() : printer_name;
293	    m_blocks       = json::array();
294	    m_next_block   = 1;
295	    m_opened       = false;
296	    // A new session's page writes its instructions again.
297	    m_instructions.clear();
298	    m_network.clear();
299	    m_credential_action.clear();
300	    m_credential_arguments = json::object();
301	    m_prepared.clear();
302	    m_search.reset();
303	    m_added.clear();
304	    m_needs_plugin = false;
305	    m_host_type.clear();
306	    m_failed_connections = 0;
307	    m_form.reset();
308	
309	    // The session is the one it was opened for. Its opener names a printer
310	    // it has just read -- a saved one, or for a change the stock profile the
311	    // project has selected -- so a name that finds neither is its bug.
312	    if ((m_mode == ConversationMode::Change && about().name.empty()) ||
313	        (m_mode == ConversationMode::Connect && saved(m_printer_name).name.empty()))
314	        throw std::logic_error("A printer conversation was opened for a printer that is not there: " + m_printer_name);
315	
316	    if (m_mode == ConversationMode::Add) {
317	        m_network = m_backend.network_printers();
318	        // A photo is the fastest way in, and the printers already on the
319	        // network are worth naming. Both sit under the opening, where the
320	        // person is deciding what to say.
321	        m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", ""}, {"kind", "tip"}});
322	        if (!m_network.empty()) {
323	            json found = json::array();
324	            for (const DiscoveredPrinter& printer : m_network)
325	                found.push_back(json{{"name", printer.name}, {"serial", printer.stable_id}, {"online", printer.connected}});
326	            m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", ""},
327	                                    {"kind", "network"}, {"printers", std::move(found)}});
328	        }
329	    }
330	    // Connecting a Bambu Lab printer that nothing can reach yet: the opening
331	    // says so, and the notice under it offers the plug-in.
332	    if (m_mode == ConversationMode::Connect && saved(m_printer_name).vendor_id == "BBL" &&
333	        m_backend.connection(m_printer_name).needs_network_plugin)
334	        show_plugin_needed({});
335	    m_host.session_changed();
336	}
