482	std::optional<Agent::SessionSkill> PrinterConversation::connection_skill() const
483	{
484	    // In force from the moment there is a saved printer to connect, before the
485	    // person asks: what they say first about connecting is read with it. A
486	    // chat that never connects carries the text (Kenneth, 2026-11-04). The
487	    // project's stock printer has no connection to make.
488	    const SavedPrinter printer = saved(m_printer_name);
489	    if (printer.name.empty())
490	        return std::nullopt;
