664	void PrinterConversation::tool_settled(const ToolActivity& activity)
665	{
666	    if (activity.tool != "settings_apply_patch" || activity.state != Agent::ToolState::Succeeded)
667	        return;
668	    const std::string saved_as = json::parse(activity.result_json).value("savedAs", std::string());
669	    if (saved_as.empty() || saved_as == m_printer_name)
670	        return;
671	    // Saved as a copy, which Orca selected in the preset's place: the
672	    // printer the person now has, and Home lists it.
673	    m_printer_name = saved_as;
674	    m_host.printers_changed(saved_as);
675	    m_host.session_changed();
676	}
677	
678	Result PrinterConversation::identify(const json& arguments, const std::string& message_id)
679	{
680	    std::vector<const CatalogPrinter*> printers;
681	    for (const json& id : arguments.at("catalogIds")) {
682	        const CatalogPrinter* printer = catalog_entry(id);
683	        if (printer == nullptr)
684	            return refuse("unknown_printer", "\"" + id.get<std::string>() + "\" is not on the printer list; copy it exactly from the printer list.");
685	        if (std::find(printers.begin(), printers.end(), printer) == printers.end())
686	            printers.push_back(printer);
687	    }
688	    if (printers.size() > kMaximumCandidates)
689	        return refuse("too_many", "More than three fit. Ask one question that narrows it down instead.");
690	    const bool stated = said_nozzle(arguments);
691	    for (const CatalogPrinter* printer : printers)
692	        if (stated && !ships(printer->nozzles, arguments["nozzle"].get<double>()))
693	            return unknown_nozzle(printer->nozzles, printer->display_name(), arguments["nozzle"].get<double>());
694	
695	    json cards = json::array();
696	    json found = json::array();
697	    const std::vector<SavedPrinter> mine = m_backend.saved_printers();
698	    for (const CatalogPrinter* printer : printers) {
699	        const double nozzle = stated ? arguments["nozzle"].get<double>() : assumed_nozzle(*printer);
700	        const bool   yours  = std::any_of(mine.begin(), mine.end(), [&](const SavedPrinter& p) { return p.model_id == printer->model_id; });
701	        cards.push_back(json{{"catalogId", printer->id}, {"name", printer->display_name()},
702	                             {"buildVolume", printer->build_volume}, {"picture", picture_data_url(printer->picture)}});
703	        found.push_back(json{{"catalogId", printer->id},
704	                             {"brand", printer->vendor_name},
705	                             {"model", printer->model_name},
706	                             {"buildVolume", printer->build_volume},
707	                             {"nozzles", printer->nozzles},
708	                             {"assumed", json{{"nozzle", nozzle},
709	                                              {"plate", nullable(printer->default_plate)},
710	                                              {"filament", nullable(printer->filament_for(nozzle))}}},
711	                             {"alreadyYours", yours}});
712	    }
713	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
714	                            {"kind", "printers"}, {"printers", std::move(cards)}});
715	    m_host.session_changed();
716	    return ok(json{{"printers", std::move(found)}});
717	}
718	
719	Result PrinterConversation::add(const json& arguments, const std::string& message_id)
720	{
721	    const std::string     id      = arguments.at("catalogId");
722	    const CatalogPrinter* printer = catalog_entry(id);
723	    if (printer == nullptr)
724	        return refuse("unknown_printer", "\"" + id + "\" is not on the printer list; copy it exactly from the printer list.");
725	    const double nozzle = said_nozzle(arguments) ? arguments["nozzle"].get<double>() : assumed_nozzle(*printer);
726	    if (!ships(printer->nozzles, nozzle))
727	        return unknown_nozzle(printer->nozzles, printer->display_name(), nozzle);
728	    // A second yes to the same printer is the same printer, not another one.
729	    if (const auto added = m_added.find(id); added != m_added.end())
730	        return refuse("already_added", "This conversation already added " + printer->display_name() + " as \"" + added->second +
731	                                           "\". To change it, use printer_change. A second printer of the same model is added by "
732	                                           "opening Add printer again.");
733	
734	    // Adding never authenticates: credentials belong to connecting, so a
735	    // failed connection cannot repeat this save.
736	    AddPrinterRequest request{printer->vendor_id,           printer->model_id,        number_text(nozzle),
737	                              printer->filament_for(nozzle), printer->display_name(), {}};
738	    SavedPrinter      added;
739	    if (const std::string problem = m_backend.add_printer(request, added); !problem.empty())
740	        return refuse("add_failed", problem);
741	    const SavedPrinter now = saved(added.name);
742	    if (now.name.empty())
743	        throw std::logic_error("A successful add did not save a printer");
744	    m_printer_name = now.name;
745	    m_added[id]    = now.name;
746	    // The receipt is the app's, drawn from what was saved: the model's reply
747	    // can word the moment any way, but whether it happened is not its to say.
748	    m_blocks.push_back(json{{"id", next_block_id()}, {"seq", m_blocks.size() + 1}, {"afterMessageId", message_id},
749	                            {"kind", "added"}, {"printer", json{{"name", now.name}, {"nozzle", now.nozzle}}}});
750	    m_host.printers_changed(now.name);
751	    m_host.session_changed();
752	    return ok(json{{"printer", printer_json(now)}});
753	}
