755	Result PrinterConversation::change(const json& arguments)
756	{
757	    // preflight_tool has checked that this is the session's own printer.
758	    const std::string  name = arguments.at("printerName");
759	    const SavedPrinter now  = saved(name);
760	    // What is loaded is the printer's to report, not the conversation's to
761	    // record: the nozzle is the one physical change this tool saves.
762	    if (!said_nozzle(arguments))
763	        return refuse("nothing_to_change", "Name the nozzle size that changed.");
764	    if (!now.nozzles.empty() && !ships(now.nozzles, arguments["nozzle"].get<double>()))
765	        return unknown_nozzle(now.nozzles, now.model.empty() ? now.name : now.model, arguments["nozzle"].get<double>());
766	
767	    ChangePrinterRequest request;
768	    request.name = name;
769	    if (arguments["nozzle"].get<double>() != now.nozzle)
770	        request.nozzle = arguments["nozzle"].get<double>();
771	    if (!request.nozzle)
772	        return refuse("nothing_to_change", "That is already how " + name + " is set up.");
773	
774	    SavedPrinter             changed;
775	    std::vector<std::string> discarded;
776	    if (const std::string problem = m_backend.change_printer(request, changed, discarded); !problem.empty())
777	        return refuse("change_failed", problem);
778	    const SavedPrinter after = saved(name);
779	    json               what  = json::array();
780	    what.push_back(json{{"field", "nozzle"}, {"before", now.nozzle}, {"after", after.nozzle}});
781	    m_host.printers_changed();
782	    m_host.session_changed();
783	    return ok(json{{"changed", std::move(what)}, {"discarded", discarded}, {"printer", printer_json(after)}});
784	}
