786	Result PrinterConversation::connection_status(const std::string& name, const std::string& message_id)
787	{
788	    if (saved(name).name.empty())
789	        return refuse("no_printer", "There is no saved printer for this conversation: add one first.");
790	    // For a Bambu Lab printer this starts looking for it on the network, once;
791	    // see m_prepared.
792	    if (m_prepared != name) {
793	        m_backend.prepare_connection(name);
794	        m_prepared = name;
795	        m_search.reset();
796	    }
797	    const PrinterConnectionInfo info = m_backend.connection(name);
798	    // A host already saved says which kind it is; until one is, the first
799	    // connection attempt does.
800	    if (info.provider == "host" && !info.address.empty() && m_host_type.empty())
801	        m_host_type = info.host_type;
802	    if (info.needs_network_plugin)
803	        show_plugin_needed(message_id);
804	    if (!m_search && info.provider == "bambu" && info.state != "unavailable")
805	        m_search = NetworkSearch{std::chrono::steady_clock::now()};
806	    // What this read lists, the model now knows: no note need say it again.
807	    // A printer already reached needs no search to report on, however it is
808	    // reached.
809	    if (m_search && (found_on_network(info) || info.state == "verified"))
810	        m_search->found = true;
811	    return ok(connection_json(info, search_json(info)));
812	}
