944	void PrinterConversation::tick(std::chrono::steady_clock::time_point now)
945	{
946	    if (m_form && m_form->reading.valid() && m_form->reading.wait_for(std::chrono::seconds(0)) == std::future_status::ready) {
947	        m_form->options = m_form->reading.get();
948	        m_host.session_changed();
949	    }
950	    watch_search(now);
951	    if (m_connecting.empty() || now - m_last_look < kConnectionLook)
952	        return;
953	    m_last_look = now;
954	    const PrinterConnectionInfo info = m_backend.connection(m_connecting);
955	    if (info.state == "connecting")
956	        return;
957	    const std::string name = m_connecting;
958	    m_connecting.clear();
959	    // A verified Moonraker host's message is the Klipper state it reported.
960	    const std::string note = m_host.post_note(info.state == "verified" ?
961	                                                  "Connection to " + name + " verified." + (info.message.empty() ? "" : " " + info.message) :
962	                                                  "Connection to " + name + " failed: " + info.message);
963	    if (info.state != "verified")
964	        connection_failed(note);
965	    m_host.printers_changed();
966	    m_host.session_changed();
967	    m_host.start_turn();
968	}
969	
970	void PrinterConversation::watch_search(std::chrono::steady_clock::time_point now)
971	{
972	    // An attempt under way is read by tick alone: reading a connection can
973	    // settle it.
974	    if (!m_search || m_search->found || !m_connecting.empty() ||
975	        now - m_search->last_look < (m_search->said_none || m_search->port != DiscoveryPort::Ours ? std::chrono::seconds(kSearchLateLook) :
976	                                                                                                       std::chrono::seconds(kConnectionLook)))
977	        return;
978	    m_search->last_look = now;
979	    const PrinterConnectionInfo info = m_backend.connection(m_prepared);
980	    // The printer was renamed or removed, or nothing can reach the network now.
981	    if (info.provider != "bambu" || info.state == "unavailable") {
982	        m_search.reset();
983	        return;
984	    }
985	    if (info.state == "verified") {
986	        m_search->found = true;
987	        return;
988	    }
989	    std::string note;
990	    if (found_on_network(info)) {
991	        m_search->found = true;
992	        bool cloud = false;
993	        for (const ConnectionCandidate& candidate : info.candidates) {
994	            if (candidate.account_only)
995	                continue;
996	            cloud = cloud || in_cloud_mode(candidate);
997	            if (offered(candidate))
998	                note += (note.empty() ? "The network search found " : "; ") + with_address(candidate) + " in LAN mode";
999	            else if (in_cloud_mode(candidate))
1000	                note += (note.empty() ? "The network search found " : "; ") + with_address(candidate) +
1001	                        " with LAN Only off, which cannot be connected as it is";
1002	            else
1003	                // Heard, and not this printer: said as such, so "found no
1004	                // printer of this model" is never the note about a printer
1005	                // the app saw.
1006	                note += (note.empty() ? "The network search heard a printer it does not offer: " : "; ") + not_offered_text(candidate);
1007	        }
1008	        note += ".";
1009	        if (cloud)
1010	            note += std::string(" ") + kPersonsChoice;
1011	    } else if (now - m_search->started < kSearchWait)
1012	        return;
1013	    else {
1014	        // Checked only once discovery has had time to bind: the check itself
1015	        // binds the port for a moment, which could cost discovery its own bind.
1016	        const DiscoveryPort port = m_backend.discovery_port();
1017	        if (port == m_search->port && (port != DiscoveryPort::Ours || m_search->said_none))
1018	            return;
1019	        m_search->port = port;
1020	        if (port == DiscoveryPort::Taken)
1021	            note = kPortTaken;
1022	        else if (port == DiscoveryPort::Free)
1023	            note = kNotListening;
1024	        else {
1025	            m_search->said_none = true;
1026	            note = "The network search has listened for " + std::to_string(kSearchWait.count()) +
1027	                   " seconds and has found no printer of this model. The app posts another note if one appears.";
1028	        }
1029	    }
1030	    m_host.post_note(note);
1031	    m_host.session_changed();
1032	    m_host.start_turn();
1033	}
