1035	// -- The panel's own page --------------------------------------------------
1036	
1037	bool PrinterConversation::handle_page_message(const std::string& type, const json& payload)
1038	{
1039	    if (type == "printer_instructions") {
1040	        // Bounded: the page's words become every request's system prompt.
1041	        const std::string text = payload.value("text", std::string());
1042	        if (text.size() <= kInstructionsLimit && text != m_instructions) {
1043	            m_instructions = text;
1044	            m_host.profile_changed();
1045	        }
1046	        return true;
1047	    }
1048	    if (type == "printer_opening") {
1049	        // The first line is the page's to write and the app's to post, once:
1050	        // a reloaded page asks again, and the thread already has it.
1051	        const std::string text = payload.value("text", std::string());
1052	        if (m_opened || text.empty() || text.size() > kNoteLimit)
1053	            return true;
1054	        m_opened                     = true;
1055	        const std::string message_id = m_host.post_opening(text);
1056	        for (json& entry : m_blocks)
1057	            if (entry.value("afterMessageId", std::string()).empty())
1058	                entry["afterMessageId"] = message_id;
1059	        m_host.session_changed();
1060	        return true;
1061	    }
1062	    if (type != "printer_action")
1063	        return false;
1064	
1065	    const std::string action = payload.value("action", std::string());
1066	    if (action == "close")
1067	        m_host.close_panel();
1068	    else if (action == "manual_setup")
1069	        open_form();
1070	    else if (action == "form_options")
1071	        ask_form_options(payload);
1072	    else if (action == "form_finish")
1073	        finish_form(payload);
1074	    else if (action == "form_close") {
1075	        m_form.reset();
1076	        m_host.session_changed();
1077	    } else if (action == "orca_printer_list") {
1078	        // OrcaSlicer's own printer list, for a panel whose page could not
1079	        // load and so cannot show the form; what it added is news the model
1080	        // answers.
1081	        const ManualPrinterResult result = m_backend.run_manual_setup();
1082	        if (!result.added.empty()) {
1083	            m_printer_name = result.added.front().name;
1084	            m_host.post_note("The person added " + m_printer_name + " from the printer list.");
1085	            m_host.printers_changed(m_printer_name);
1086	            m_host.session_changed();
1087	            m_host.start_turn();
1088	        }
1089	    } else if (action == "connect" && payload.value("actionId", std::string()) == m_credential_action &&
1090	               payload.contains("credential") && payload["credential"].is_string()) {
1091	        const json arguments = std::move(m_credential_arguments);
1092	        m_credential_action.clear();
1093	        m_credential_arguments = json::object();
1094	        connect(arguments, payload["credential"].get<std::string>());
1095	    } else if (action == "open_printer_settings" && !m_printer_name.empty()) {
1096	        m_backend.open_printer_settings(m_printer_name);
1097	        m_host.printers_changed();
1098	        m_host.session_changed();
1099	    } else if (action == "undo_add")
1100	        undo_add(payload.value("blockId", std::string()));
1101	    else if (action == "install_network_plugin")
1102	        install_network_plugin();
1103	    else if (action == "report_send" || action == "report_decline")
1104	        answer_report(payload.value("blockId", std::string()), action == "report_send");
1105	    return true;
1106	}
1107	
1108	void PrinterConversation::undo_add(const std::string& block_id)
1109	{
1110	    json* receipt = nullptr;
1111	    for (json& block : m_blocks)
1112	        if (block.value("id", std::string()) == block_id && block.value("kind", std::string()) == "added")
1113	            receipt = &block;
1114	    // A second tap that arrived before the page redrew the first has nothing
1115	    // left to undo.
1116	    if (receipt == nullptr || receipt->value("removed", false))
1117	        return;
1118	
1119	    // Orca's own delete, as Home's "Remove printer…" runs it: the printer the
1120	    // project was set up for gives way to the profile it was based on.
1121	    const std::string name = receipt->at("printer").at("name");
1122	    if (const std::string problem = m_backend.remove_printer(name); !problem.empty()) {
1123	        m_host.post_note("Undo did not remove " + name + ": " + problem);
1124	        m_host.session_changed();
1125	        return;
1126	    }
1127	    // printer_add saves a printer based on a shipped profile, which Orca
1128	    // deletes without asking; only a printer of the person's own design can
1129	    // be kept by declining there.
1130	    if (!saved(name).name.empty())
1131	        throw std::logic_error("Removing an added printer left it saved");
1132	
1133	    if (m_connecting == name)
1134	        abandon_connection();
1135	    (*receipt)["removed"] = true;
1136	    // The same printer can now be added again, and nothing here is about it.
1137	    for (auto added = m_added.begin(); added != m_added.end();)
1138	        added = added->second == name ? m_added.erase(added) : std::next(added);
1139	    if (m_printer_name == name)
1140	        m_printer_name.clear();
1141	    if (m_prepared == name) {
1142	        m_prepared.clear();
1143	        m_search.reset();
1144	    }
1145	    m_host.post_note("The person tapped Undo on the receipt: " + name + " is removed and is no longer one of their printers.");
1146	    m_host.printers_changed();
1147	    m_host.session_changed();
1148	    m_host.start_turn();
1149	}
