774	std::string OrcaPrinterBackend::connect_host(const std::string& name, const std::string& host_type,
775	                                            const std::string& address, const std::string& api_key)
776	{
777	    const auto info = connection(name);
778	    if (info.provider != "host" || info.state == "unavailable")
779	        return info.message;
780	    if (host_type != "moonraker" && host_type != "octoprint")
781	        return "Choose Moonraker or OctoPrint.";
782	    if (address.empty() || address.find_first_of("\r\n\t @") != std::string::npos)
