846	        // key refused, "doesn't look like Moonraker" is another kind of
847	        // host, and curl's reason is the host not reached. One sentence for
848	        // all three sent people to check the network when the host had
849	        // answered.
850	        attempt.state          = "failed";
851	        const std::string said = one_line(*attempt.detail);
852	        attempt.message        = (said.empty() ? "The print host test failed, and it gave no reason." :
853	                                                 "The print host test failed: " + said) + " " + attempt.key_sent;
854	        break;
855	    }
856	    case HostVerdict::Testing:
857	        if (std::chrono::steady_clock::now() - attempt.started > kConnectionWait) {
