510	PrinterConnectionInfo OrcaPrinterBackend::connection(const std::string& name)
511	{
512	    PrinterConnectionInfo info;
513	    const auto saved = saved_printers();
514	    const auto printer = std::find_if(saved.begin(), saved.end(), [&](const SavedPrinter& p) { return p.name == name; });
515	    if (printer == saved.end()) {
516	        info.state = "unavailable";
517	        info.message = "This printer was renamed or removed. Open it again from Printers.";
518	        return info;
519	    }
520	    const CatalogPrinter* model = model_of(name);
521	    if (!model || model->vendor_id != "BBL") {
522	        const Preset* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
523	        if (!preset)
524	            throw std::logic_error("A saved printer has no preset");
525	        if (m_host_attempt && m_host_attempt->name == name && m_host_attempt->state == "connecting")
526	            settle(*m_host_attempt);
527	        const auto type = preset->config.opt_enum<PrintHostType>("host_type");
528	        info.address = preset->config.opt_string("print_host");
529	        info.host_type = type == htMoonraker ? "moonraker" : type == htOctoPrint ? "octoprint" : "other";
530	        info.provider = "host";
531	        info.state = info.address.empty() ? "not_configured" : "unknown";
532	        if (info.state == "unknown")
533	            info.message = "A connection is saved. Test it to check access; live printer status is not available here.";
534	        if (info.host_type == "other") {
535	            // The type the printer is saved with, as OrcaSlicer labels it.
536	            const ConfigOptionDef* types = preset->config.def()->get("host_type");
537	            const std::string      saved = preset->config.option("host_type")->serialize();
538	            const auto             found = std::find(types->enum_values.begin(), types->enum_values.end(), saved);
539	            const std::string      label = found == types->enum_values.end() ? saved :
540	                                                                                types->enum_labels[found - types->enum_values.begin()];
541	            info.state   = "unavailable";
542	            info.message = "This printer is saved with the " + label + " connection type, which this chat does not connect: it "
543	                           "connects Moonraker and OctoPrint. You can still prepare prints and export a file.";
544	        }
545	        if (m_host_attempt && m_host_attempt->name == name) {
546	            auto& attempt = *m_host_attempt;
547	            // Only a verified attempt saved its settings; it holds while the
548	            // printer is still set up as it was tested.
549	            if (attempt.state == "verified" &&
550	                (info.address != attempt.address || info.host_type != attempt.host_type ||
551	                 preset->config.opt_string("printhost_apikey") != attempt.api_key)) {
552	                info.message = "Connection settings changed. Test the new connection again.";
553	                return info;
554	            }
555	            info.state = attempt.state;
556	            info.message = attempt.message;
557	        }
558	        return info;
559	    }
560	    info.provider = "bambu";
561	    info.device_id = printer->device_id;
562	    auto* devices = wxGetApp().getDeviceManager();
563	    auto* agent = wxGetApp().getAgent();
564	    info.signed_in = agent && agent->is_user_login(BBL_CLOUD_PROVIDER);
565	    if (fake_bambu_printer_agent_id(wxGetApp().app_config).empty() && !NetworkAgent::is_network_module_loaded()) {
566	        info.state = "unavailable";
567	        info.needs_network_plugin = true;
568	        const auto load_error = NetworkAgent::get_load_error();
569	        info.message = "Connecting a Bambu Lab printer needs Bambu's network plug-in, which is not loaded" +
570	                       (load_error.has_error ? ": " + load_error.message : std::string()) +
571	                       ". The person can already prepare prints for this printer without it.";
572	        return info;
573	    }
574	    if (!devices || !agent) {
575	        info.state = "unavailable";
576	        info.message = "Connecting is not available right now. The person can already prepare prints for this printer.";
577	        return info;
578	    }
579	    // The local list is what has announced itself on this network; the cloud
580	    // list is the person's account, wherever those printers are.
581	    auto nearby = devices->get_local_machinelist();
582	    // For the harness's no-printer chat (JUSPRIN_TEST_HEAR_NOTHING): no printer
583	    // is heard, whatever the real printer announces.
584	    if (std::getenv("JUSPRIN_TEST_HEAR_NOTHING") != nullptr)
585	        nearby.clear();
586	    auto candidates = nearby;
587	    for (const auto& entry : devices->get_my_cloud_machine_list())
588	        candidates[entry.first] = entry.second;
589	    // Every printer the app knows of is listed. One it does not offer carries
590	    // the reason, so the model is never told "found no printer" about a
591	    // printer the app chose not to offer (the P1S case of 2026-10-31, and the
592	    // sweep after it).
593	    for (const auto& [id, machine] : candidates) {
594	        if (!machine)
595	            continue;
596	        ConnectionCandidate candidate{id, machine->get_dev_name(), machine->get_dev_ip(), machine->is_lan_mode_printer(),
597	                                      nearby.find(id) == nearby.end()};
598	        const auto linked_to = std::find_if(saved.begin(), saved.end(), [&](const SavedPrinter& p) {
599	            return p.name != name && p.device_id == id;
600	        });
601	        if (machine->printer_type != model->device_model_id) {
602	            candidate.reason = "other_model";
603	            candidate.detail = machine->get_printer_type_display_str().ToUTF8().data();
604	        } else if (!info.device_id.empty() && id != info.device_id) {
605	            candidate.reason = "other_device";
606	            candidate.detail = info.device_id;
607	        } else if (linked_to != saved.end()) {
608	            candidate.reason = "linked_elsewhere";
609	            candidate.detail = linked_to->name;
610	        } else if (machine->is_lan_mode_printer() && !machine->is_avaliable()) {
611	            candidate.reason = "occupied";
612	        }
613	        info.candidates.push_back(std::move(candidate));
614	    }
615	    MachineObject* machine = info.device_id.empty() ? nullptr : devices->get_my_machine(info.device_id);
616	    // is_connected() alone is optimistic immediately after reset(). Require
617	    // actual parsed push data, and fresh LAN data for a LAN connection.
618	    const bool communicating = machine && has_recent_printer_data(*machine);
619	    const bool configured = has_verified_printer_connection(info.device_id);
620	    info.state = communicating ? "verified" : configured ? "unknown" : "not_configured";
621	    if (info.state == "unknown")
622	        info.message = "The app has no recent data from this printer.";
623	    if (m_connection_attempt && m_connection_attempt->name == name) {
624	        const auto& attempt = *m_connection_attempt;
625	        if (info.device_id != attempt.device_id)
626	            throw std::logic_error("A connection attempt lost its saved printer association");
627	        const bool observed = communicating &&
628	            (machine->is_lan_mode_printer() ? machine->last_lan_msg_time_ > attempt.observation_start
629	                                           : machine->last_cloud_msg_time_ > attempt.observation_start);
630	        // What the plug-in answered to this attempt comes first: upstream's
631	        // handler clears the selection and erases a wrong access code on a
632	        // failure, and reading that state alone named the wrong cause.
633	        const auto answered = Printers::last_connection_event(attempt.device_id);
634	        if (answered && !attempt.reselecting && answered->at >= attempt.connect_requested &&
635	            answered->kind != Printers::ConnectionEvent::Kind::Ok) {
636	            // The printer answered a wrong code, so its port needs no look.
637	            report_failure(info, connection_failure_text(*answered, attempt.connect_requested), answered->code != "5");
638	        } else if (devices->get_selected_machine() != machine && machine != nullptr && !attempt.reselecting) {
639	            info.state = "failed";
640	            info.message = "The selected printer changed. Select this printer again to reconnect.";
641	        } else if (observed) {
642	            info.state = "verified";
643	            m_connection_attempt.reset();
644	        } else if (machine == nullptr) {
645	            info.state = "failed";
646	            info.message = "The printer is no longer available. Refresh the printer list and try again.";
647	        } else if (std::chrono::steady_clock::now() - attempt.started > kConnectionWait) {
648	            report_failure(info, "The printer did not respond within " + std::to_string(kConnectionWait.count()) + " seconds.", true);
649	        } else {
650	            info.state = "connecting";
651	            info.message.clear();
652	        }
653	    }
654	    if (info.state == "verified")
655	        wxGetApp().app_config->set("jusprin_verified_connections", info.device_id, "true");
656	    if (communicating) {
657	        const auto* extruders = machine->GetExtderSystem();
658	        info.nozzle_mismatch = extruders && extruders->GetNozzleDiameter(0) > 0 &&
659	            std::abs(extruders->GetNozzleDiameter(0) - printer->nozzle) > 0.001;
660	    }
661	    return info;
662	}
663	
664	// On a thread of its own, as a print host's test is: a printer that does not
665	// answer would hold the app for the whole limit.
666	std::shared_ptr<OrcaPrinterBackend::PortLook> OrcaPrinterBackend::start_port_look(const std::string& address)
667	{
668	    auto look = std::make_shared<PortLook>();
669	    std::thread([look, address] {
670	        look->said = Printers::look_at_port(address, kBambuLanPort, kPortLookLimit);
671	        look->done.store(true);
672	    }).detach();
673	    return look;
674	}
675	
676	void OrcaPrinterBackend::report_failure(PrinterConnectionInfo& info, const std::string& failure, bool look)
677	{
678	    auto& attempt = *m_connection_attempt;
679	    if (!look || attempt.address.empty()) {
680	        info.state   = "failed";
681	        info.message = failure;
682	        return;
683	    }
684	    // The attempt keeps reading "connecting" until both looks are back, so its
685	    // note says everything at once.
686	    if (!attempt.port_after)
687	        attempt.port_after = start_port_look(attempt.address);
688	    if (!attempt.port_before->done.load() || !attempt.port_after->done.load()) {
689	        info.state = "connecting";
690	        info.message.clear();
691	        return;
692	    }
693	    info.state   = "failed";
694	    info.message = failure + " The app also tried the printer's port " + std::to_string(kBambuLanPort) + " at " + attempt.address +
695	                   ". Just before the attempt, " + attempt.port_before->said + ". Right after it failed, " + attempt.port_after->said + ".";
696	}
