698	std::string OrcaPrinterBackend::keep_connection_report(const std::string& text)
699	{
700	    const std::filesystem::path folder = std::filesystem::u8path(Slic3r::data_dir()) / "jusprin" / "connection_reports";
701	    std::error_code             failed;
702	    std::filesystem::create_directories(folder, failed);
703	    const auto seconds = std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count();
704	    const std::filesystem::path path = folder / ("report-" + std::to_string(seconds) + ".json");
705	    std::ofstream               file(path, std::ios::binary);
706	    file << text;
707	    file.close();
708	    return file.good() ? path.u8string() : std::string();
709	}
710	
711	std::string OrcaPrinterBackend::connect_printer(const std::string& name, const std::string& device_id,
712	                                               const std::string& access_code)
713	{
714	    // The same printer asked for again keeps waiting; anything else replaces
715	    // the attempt below. One that has failed and is only having its port looked
716	    // at is over, though it still reads "connecting".
717	    if (m_connection_attempt && m_connection_attempt->name == name && m_connection_attempt->device_id == device_id &&
718	        connection(name).state == "connecting" && !m_connection_attempt->port_after)
719	        return {};
720	    const auto info = connection(name);
721	    if (info.provider != "bambu" || info.state == "unavailable")
722	        return info.message;
723	    const auto chosen = std::find_if(info.candidates.begin(), info.candidates.end(), [&](const ConnectionCandidate& p) { return p.id == device_id; });
724	    if (chosen == info.candidates.end())
725	        return "That printer is not on the list for this connection. Choose one from the list.";
726	    if (!chosen->reason.empty())
727	        return "That printer cannot be chosen (" + chosen->reason + "). Choose another from the list.";
728	    auto* devices = wxGetApp().getDeviceManager();
729	    MachineObject* machine = devices->get_my_machine(device_id);
730	    if (!machine)
731	        machine = devices->get_local_machine(device_id);
732	    if (!machine)
733	        return "That printer is no longer available. Refresh the list and try again.";
734	    if (machine->is_lan_mode_printer()) {
735	        if (access_code.empty() && !machine->has_access_right())
736	            return "Enter the access code shown on your printer.";
737	        if (!std::all_of(access_code.begin(), access_code.end(), [](unsigned char c) {
738	                return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
739	            }))
740	            return "The access code can only contain letters and numbers.";
741	    }
742	    const wxString problem = Printers::link_named_printer(name, device_id);
743	    if (!problem.empty())
744	        return problem.ToStdString();
745	    prepare_connection(name);
746	    if (machine->is_lan_mode_printer() && !access_code.empty())
747	        machine->set_user_access_code(access_code);
748	    m_connection_attempt = ConnectionAttempt{name, device_id, std::chrono::steady_clock::now(),
749	                                              std::chrono::system_clock::now(), std::chrono::steady_clock::now()};
750	    if (machine->is_lan_mode_printer() && !machine->get_dev_ip().empty()) {
751	        m_connection_attempt->address     = machine->get_dev_ip();
752	        m_connection_attempt->port_before = start_port_look(m_connection_attempt->address);
753	    }
754	    if (devices->get_selected_machine() != machine) {
755	        devices->set_selected_machine(device_id);
756	        return {};
757	    }
758	    // Selecting the selected LAN printer again disconnects and reconnects
759	    // it, and GUI_App's local-connect handler hears the disconnect one event
760	    // turn later and clears the selection -- after the reconnect. Deselect
761	    // now, and select it again once that notice has run.
762	    m_connection_attempt->reselecting = true;
763	    devices->set_selected_machine("");
764	    wxGetApp().CallAfter([alive = std::weak_ptr<bool>(m_alive), this, device_id] {
765	        if (alive.expired() || !m_connection_attempt || m_connection_attempt->device_id != device_id)
766	            return;
767	        m_connection_attempt->reselecting       = false;
768	        m_connection_attempt->connect_requested = std::chrono::steady_clock::now();
769	        wxGetApp().getDeviceManager()->set_selected_machine(device_id);
770	    });
771	    return {};
772	}
