774	std::string OrcaPrinterBackend::connect_host(const std::string& name, const std::string& host_type,
775	                                            const std::string& address, const std::string& api_key)
776	{
777	    const auto info = connection(name);
778	    if (info.provider != "host" || info.state == "unavailable")
779	        return info.message;
780	    if (host_type != "moonraker" && host_type != "octoprint")
781	        return "Choose Moonraker or OctoPrint.";
782	    if (address.empty() || address.find_first_of("\r\n\t @") != std::string::npos)
783	        return "Enter the printer's host name, IP address or HTTP URL without credentials.";
784	    if (address.find("://") != std::string::npos && address.rfind("http://", 0) != 0 && address.rfind("https://", 0) != 0)
785	        return "Use an HTTP or HTTPS address.";
786	    const auto* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
787	    if (!preset)
788	        return "This printer was renamed or removed.";
789	    // Reuse a saved secret only for the same endpoint and provider.
790	    const std::string key = api_key.empty() && address == info.address && host_type == info.host_type ?
791	        preset->config.opt_string("printhost_apikey") : api_key;
792	    // A 401 reads the same for no key and a wrong one, so a failure says
793	    // which was sent.
794	    const std::string key_sent = !api_key.empty() ? "The test sent the API key typed in the form." :
795	                                 !key.empty()     ? "The form was left empty, so the test sent the API key saved for this printer." :
796	                                                    "The form was left empty, and the test sent no API key.";
797	    // Tested on a copy: the printer's own settings change only once the host
798	    // has answered (settle).
799	    DynamicPrintConfig config = preset->config;
800	    config.set_key_value("host_type", new ConfigOptionEnum<PrintHostType>(host_type == "moonraker" ? htMoonraker : htOctoPrint));
801	    config.set_key_value("print_host", new ConfigOptionString(address));
802	    config.set_key_value("printhost_apikey", new ConfigOptionString(key));
803	    std::unique_ptr<PrintHost> host(host_type == "moonraker" ? new MoonrakerKeepingState(&config) : PrintHost::get_print_host(&config));
804	    if (!host)
805	        throw std::logic_error("A supported print host has no adapter");
806	    // PrintHost::test blocks until the host answers, and a host that accepts
807	    // the connection and never replies holds it with no upper bound (Http's
808	    // DEFAULT_TIMEOUT_MAX is 0). So it runs on a thread of its own, as
809	    // upstream's upload queue runs these adapters. Nothing waits for it:
810	    // joining could hold the panel's close for as long as the host dawdles,
811	    // and kConnectionWait reports the failure meanwhile. The adapter keeps
812	    // copies of what it read from `config`.
813	    auto verdict = std::make_shared<std::atomic<HostVerdict>>(HostVerdict::Testing);
814	    auto detail  = std::make_shared<std::string>();
815	    std::thread([host = std::move(host), verdict, detail] {
816	        wxString said;
817	        const bool passed = host->test(said);
818	        // Written before the verdict, which the reader loads first.
819	        *detail = said.ToUTF8().data();
820	        verdict->store(passed ? HostVerdict::Passed : HostVerdict::Failed);
821	    }).detach();
822	    m_host_attempt = HostAttempt{name, host_type, address, key, std::chrono::steady_clock::now(), std::move(verdict), std::move(detail),
823	                                 "connecting", {}, key_sent};
824	    return {};
825	}
826	
827	void OrcaPrinterBackend::settle(HostAttempt& attempt)
828	{
829	    switch (attempt.verdict->load()) {
830	    case HostVerdict::Passed: {
831	        const wxString problem = Printers::configure_named_printer_host(
832	            attempt.name, attempt.host_type == "moonraker" ? htMoonraker : htOctoPrint, attempt.address, attempt.api_key);
833	        attempt.state   = problem.empty() ? "verified" : "failed";
834	        attempt.message = problem.ToStdString();
835	        // The test's answer is Home's first word on this host.
836	        if (problem.empty())
837	            Printers::note_host_answered(attempt.name);
838	        // Moonraker answers while Klipper is shut down or in error, so a pass
839	        // says what state it reported.
840	        if (problem.empty() && attempt.host_type == "moonraker")
841	            attempt.message = "Moonraker reports Klipper's state as " + *attempt.detail + ".";
842	        break;
843	    }
844	    case HostVerdict::Failed: {
845	        // The host's own answer travels with the failure: "HTTP 401" is the
846	        // key refused, "doesn't look like Moonraker" is another kind of
847	        // host, and curl's reason is the host not reached. One sentence for
848	        // all three sent people to check the network when the host had
849	        // answered.
850	        attempt.state          = "failed";
851	        const std::string said = one_line(*attempt.detail);
852	        attempt.message        = (said.empty() ? "The print host test failed, and it gave no reason." :
853	                                                 "The print host test failed: " + said) + " " + attempt.key_sent;
854	        break;
855	    }
856	    case HostVerdict::Testing:
857	        if (std::chrono::steady_clock::now() - attempt.started > kConnectionWait) {
858	            attempt.state   = "failed";
859	            // What the app saw, without a cause: a name this computer cannot
860	            // look up waits here as long as a host that never answers.
861	            attempt.message = "The print host test had no answer from " + attempt.address + " after " +
862	                              std::to_string(kConnectionWait.count()) + " seconds.";
863	        }
864	        break;
865	    }
866	}
867	
868	void OrcaPrinterBackend::cancel_connection(const std::string& name)
869	{
870	    if (m_host_attempt && m_host_attempt->name == name && m_host_attempt->state == "connecting")
871	        m_host_attempt.reset();
872	    // A Bambu Lab printer stays linked to the device and selected, as after a
873	    // failure; undoing both is separate work.
874	    if (m_connection_attempt && m_connection_attempt->name == name)
875	        m_connection_attempt.reset();
876	}
