Result PrinterConversation::host_connect(const json& arguments, const ToolActivity& activity)
{
    const std::string name       = arguments.at("printerName");
    const std::string action_id  = activity.action_id;
    const std::string message_id = activity.correlation_id;
    // A key the app holds for that address is sent; none otherwise.
    const std::string problem = m_backend.connect_host(name, arguments.at("hostType"), arguments.at("address"), {},
                                                       [this, action_id, arguments, message_id](const HostTestOutcome& outcome) {
                                                           host_tested(action_id, arguments, message_id, outcome);
                                                       });
    // preflight_tool has checked the printer; what is left is the address.
    if (!problem.empty())
        return refuse("invalid_arguments", problem);
    abandon_connection();
    m_host_testing = name;
    m_host_call    = action_id;
    Result waiting;
    waiting.handled = true;
    waiting.pending = true;
    return waiting;
}

void PrinterConversation::host_tested(const std::string& action_id, const json& arguments, const std::string& message_id,
                                      const HostTestOutcome& outcome)
{
    m_host_testing.clear();
    m_host_call.clear();
    std::string message = outcome.message;
    // The host wants a key: the person types one in the form, never in chat.
    if (outcome.state == "needs_credential") {
        m_credential_action    = action_id;
        m_credential_arguments = arguments;
        message += std::string(" Because of that answer, the app has opened a form in this chat where the person can type ") +
                   (outcome.key == "saved" ? "a different" : "an") +
                   " API key. When they submit it, the app tests again with that key and posts the outcome in a note.";
    }
    if (outcome.state != "verified")
        if (const std::string report = connection_failed(message_id); !report.empty())
            message += " " + report;
    m_host.printers_changed();
    m_host.session_changed();
    if (m_host.finish_tool(action_id, ok(json{{"state", outcome.state}, {"message", message}})))
        return;
    // The call was stopped meanwhile: nothing waits for the form.
    if (m_credential_action == action_id) {
        m_credential_action.clear();
        m_credential_arguments = json::object();
        m_host.session_changed();
    }
}

