-//              a P1S, opens its Connect chat and runs printer_connect and
+//              a P1S, opens its Connect chat and runs printer_bambu_connect and
@@ -274,0 +275,11 @@
+//   --printer-direct-connect <fixture-directory> <address> <plug-in-version> [backend | monitor] [ssl-off]
+//              no model, no fake and no chat: a real Bambu Lab printer in LAN
+//              mode at <address>, with the real plug-in in the fixture
+//              directory as for --printer-network-check. Saves a P1S, waits for
+//              the printer's announcement, stores the access code from
+//              JUSPRIN_P1S_CODE (never printed) and selects the machine, as
+//              Orca's own device list does, then prints the plug-in's answer
+//              and any message Orca puts up. With backend, connects through
+//              the printer chat's connection code instead, and prints what it
+//              reports; with monitor, opens Home's monitor window on it. With
+//              ssl-off, Orca's Enable SSL(MQTT) preference is off
@@ -309,5 +320,8 @@
-//              no model: the app's own print host test against each line of
-//              "<moonraker|octoprint> <address> [<variable holding the key>]",
-//              printing what the printer chat would be told, for the printer
-//              named (such as "Elegoo/Elegoo Neptune 4 Pro") or the first one
-//              not made by Bambu Lab.
+//              no model: a printer chat's connection tool called once per
+//              line of "<moonraker|octoprint> <address> [<variable holding the
+//              key> | MISSING | CANCEL]", printing what the model reads back.
+//              When the host asks for a key the call waits on the form, which
+//              is submitted with that variable's value (or empty), or answered
+//              with its "no key" or Cancel button. For the printer named
+//              (such as "Elegoo/Elegoo Neptune 4 Pro") or the first one not
+//              made by Bambu Lab.
@@ -442,0 +457 @@
+#include <wx/stattext.h>
